-- 207 — Mejora 9, tercera parte (Juan, 2026-11-11: «ok»): los códigos UNSPSC de cada experiencia del RUP y la propuesta
-- de experiencia para cada oferta.
--
-- Para proponer qué contratos van a la experiencia habilitante y a la ponderable hay que saber qué códigos tiene cada
-- contrato: los pliegos los exigen (Fiscalía: 92121500, 92121700 y 46171600). La ficha sólo tenía cuántos contratos
-- tiene cada código (psi_company_rup_codes), no cuáles.
--
-- Fuente: RUP de la Cámara de Comercio de Pereira expedido el 2026-11-03 (`21_RUP_SEGURIDAD_NACIONAL_2026-11-03_VIGENTE.pdf`,
-- sha256 042dfe8dc683f805ef2e584a…, 62 páginas escaneadas), leído con OCR (tesseract, español) el 2026-11-11. Comprobado: los 101
-- consecutivos coinciden con los de la 194, y el número de contratos por código coincide exacto con los 14 códigos de
-- psi_company_rup_codes (92121500: 101, 92121700: 79, 46171600: 66, …). Sólo se llena donde la columna está vacía.
begin;

alter table public.psi_company_experience add column if not exists unspsc_codes text[];
comment on column public.psi_company_experience.unspsc_codes is
  'Códigos UNSPSC del contrato según el RUP (8 dígitos). Los pliegos exigen experiencia con ciertos códigos.';

update public.psi_company_experience e
set unspsc_codes = v.codigos, updated_at = now()
from (values
