-- La propuesta de Vig-IA para cada licitación: qué contratos van a la experiencia habilitante y cuáles a la ponderable,
-- con lo que pide el pliego. Vig-IA propone; una persona acepta o cambia (`selection`).
create table if not exists public.psi_tender_experience_plans (
  opportunity_id uuid primary key references public.psi_sales_opportunities(id) on delete cascade,
  analysis_run_id uuid,
  proposal jsonb not null,
  selection jsonb,
  selection_by uuid references public.psi_sales_profiles(id) on delete set null,
  selection_at timestamptz,
  created_by uuid references public.psi_sales_profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
alter table public.psi_tender_experience_plans enable row level security;
revoke all on table public.psi_tender_experience_plans from public, anon, authenticated, service_role;
grant select, insert, update on table public.psi_tender_experience_plans to service_role;

commit;
